// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue } from '@skyramp/skyramp';
import { createUser, deleteUser, createCollection, updateCollection, deleteCollection, getCollectionMembers, deleteCollectionMember } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const usersPostRequestBody: string = `{
        "name": "Testbot Removal Member",
        "password": "testbotpassword123",
        "username": "testbot-removal-member"
    }`;

    const usersPostResponse = await createUser(client, URL_localhost, usersPostRequestBody, "testbot-removal-member", 201);
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^testbot-removal-member-/);
    expect(getResponseValue(usersPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const memberUserId = getResponseValue(usersPostResponse, "response.id");

    // Request Body
    const collectionsPostRequestBody: string = `{
        "description": "testbot removal fixture",
        "name": "Testbot Removal Fixture"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, collectionsPostRequestBody, 200);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Testbot Removal Fixture");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("testbot removal fixture");
    expect(getResponseValue(collectionsPostResponse, "response.ownerId"), 'ownerId').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const ownerUserId = getResponseValue(collectionsPostResponse, "response.ownerId");

    // Request Body
    const collectionsCollectionsPutRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "testbot removal fixture",
        "id": 7422,
        "isPublic": false,
        "members": [
            {
                "canCreate": false,
                "canDelete": false,
                "canUpdate": false,
                "userId": 7311
            }
        ],
        "name": "Testbot Removal Fixture",
        "ownerId": 5933
    }`;

    const collectionsCollectionsPutResponse = await updateCollection(client, URL_localhost, collectionId, collectionsCollectionsPutRequestBody, ownerUserId, memberUserId, 200);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.id"), 'updated collection id').toBe(collectionId);

    const collectionsMembersGetResponse = await getCollectionMembers(client, URL_localhost, collectionId, 200);
    expect(collectionsMembersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsMembersGetResponse, "response").length, 'member count after add').toBe(1);
    expect(getResponseValue(collectionsMembersGetResponse, "response.0.userId"), 'member userId').toBe(memberUserId);
    expect(getResponseValue(collectionsMembersGetResponse, "response.1"), 'second member').toBeNull();

    const membersGetResponse = await getCollectionMembers(client, URL_localhost, "abc", 400);
    expect(membersGetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(membersGetResponse, "response"), 'error body').toBe("Invalid collection ID.");

    const collectionsMembersGet1Response = await getCollectionMembers(client, URL_localhost, 999999, 404);
    expect(collectionsMembersGet1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(collectionsMembersGet1Response, "response"), 'error body').toBe("Collection not found.");

    const collectionsMembersDeleteResponse = await deleteCollectionMember(client, URL_localhost, collectionId, {}, 400);
    expect(collectionsMembersDeleteResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersDeleteResponse, "response"), 'error body').toBe("userId query param is required.");

    const collectionsMembersDelete1Response = await deleteCollectionMember(client, URL_localhost, collectionId, {"userId": [ownerUserId]}, 400);
    expect(collectionsMembersDelete1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersDelete1Response, "response"), 'error body').toBe("Owner cannot remove themselves.");

    const collectionsMembersDelete2Response = await deleteCollectionMember(client, URL_localhost, collectionId, {"userId": [memberUserId]}, 200);
    expect(collectionsMembersDelete2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsMembersDelete2Response, "response"), 'removal body').toBe("Member removed.");

    const collectionsMembersGet2Response = await getCollectionMembers(client, URL_localhost, collectionId, 200);
    expect(collectionsMembersGet2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsMembersGet2Response, "response").length, 'member count after removal').toBe(0);
    expect(getResponseValue(collectionsMembersGet2Response, "response.0"), 'first member after removal').toBeNull();

    const collectionsMembersDelete3Response = await deleteCollectionMember(client, URL_localhost, collectionId, {"userId": [999999]}, 404);
    expect(collectionsMembersDelete3Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(collectionsMembersDelete3Response, "response"), 'error body').not.toBe("Member removed.");

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, collectionId, 200);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);

    const usersUsersDeleteResponse = await deleteUser(client, URL_localhost, memberUserId, 200);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'delete user body').toBe("User account and all related data deleted successfully.");
});
